import{_ as e,C as t,c as i,o as r,a0 as l,b as a,w as n,a as s,G as o,a1 as k}from"./chunks/framework.DKRgXLPU.js";const d=JSON.parse('{"title":"Teamkommunikasjon","description":"","frontmatter":{},"headers":[],"relativePath":"no/education/team-player/communication.md","filePath":"no/education/team-player/communication.md"}');const m=e({name:"no/education/team-player/communication.md"},[["render",function(e,d,m,u,g,p){const h=t("Mermaid");return r(),i("div",null,[d[1]||(d[1]=l('<h1 id="teamkommunikasjon" tabindex="-1">Teamkommunikasjon <a class="header-anchor" href="#teamkommunikasjon" aria-label="Permalink to &quot;Teamkommunikasjon&quot;">​</a></h1><p>Effektiv kommunikasjon er det som forvandler en gruppe individer til et team. I petanque, hvor strategien stadig endres og presset er høyt, kan måten du kommuniserer på avgjøre resultatet.</p><div class="tip custom-block"><p class="custom-block-title">Den store ideen</p><p><strong>Kommunikasjon er det som forvandler individer til et team.</strong> Tydelig, spesifikk og støttende kommunikasjon under press skiller gode team fra fantastiske team.</p></div><h2 id="kommunikasjonssyklusen" tabindex="-1">Kommunikasjonssyklusen <a class="header-anchor" href="#kommunikasjonssyklusen" aria-label="Permalink to &quot;Kommunikasjonssyklusen&quot;">​</a></h2><p>God teamkommunikasjon følger en syklus:</p>',5)),(r(),a(k,null,{default:n(()=>[o(h,{id:"mermaid-17",class:"mermaid",graph:"graph%20LR%0A%20%20%20%20A%5BObservere%5D%20--%3E%20B%5BDele%5D%0A%20%20%20%20B%20--%3E%20C%5BDiskutere%5D%0A%20%20%20%20C%20--%3E%20D%5BAvgj%C3%B8re%5D%0A%20%20%20%20D%20--%3E%20E%5BHenrette%5D%0A%20%20%20%20E%20--%3E%20F%5BAnmeldelse%5D%0A%20%20%20%20F%20--%3E%20A%0A%0A%20%20%20%20style%20A%20fill%3A%23e3f2fd%0A%20%20%20%20style%20D%20fill%3A%23e8f5e9%0A%20%20%20%20style%20E%20fill%3A%23fff4e1%0A%20%20%20%20style%20F%20fill%3A%23f3e5f5%0A"})]),fallback:n(()=>[...d[0]||(d[0]=[s(" Loading... ",-1)])]),_:1})),d[2]||(d[2]=l('<table tabindex="0"><thead><tr><th>Skritt</th><th>Handling</th><th>Eksempel</th></tr></thead><tbody><tr><td><strong>Observere</strong></td><td>Legg merke til hva som skjer</td><td>Terreng, posisjoner, motstandere</td></tr><tr><td><strong>Dele</strong></td><td>Fortell lagkameratene hva du ser</td><td>&quot;Jorden skråner der igjen&quot;</td></tr><tr><td><strong>Diskutere</strong></td><td>Utvekslingsperspektiver</td><td>&quot;Bør jeg blokkere eller gå for poeng?&quot;</td></tr><tr><td><strong>Avgjøre</strong></td><td>Enig om tilnærming</td><td>&quot;La oss prøve den høye lobben&quot;</td></tr><tr><td><strong>Henrette</strong></td><td>Gjør det med engasjement</td><td>Fullt fokus på kastet</td></tr><tr><td><strong>Anmeldelse</strong></td><td>Lær av resultatet</td><td>«Det fungerte bra» eller «Neste gang...»</td></tr></tbody></table><h2 id="nar-man-skal-kommunisere" tabindex="-1">Når man skal kommunisere <a class="header-anchor" href="#nar-man-skal-kommunisere" aria-label="Permalink to &quot;Når man skal kommunisere&quot;">​</a></h2><h3 id="før-hver-ende" tabindex="-1">Før hver ende <a class="header-anchor" href="#før-hver-ende" aria-label="Permalink to &quot;Før hver ende&quot;">​</a></h3><ul><li>Vurder terrenget sammen</li><li>Diskuter generell tilnærming</li><li>Avklar hvem som kaster når</li><li>Sett tonen (rolig, fokusert)</li></ul><h3 id="under-slutten" tabindex="-1">Under slutten <a class="header-anchor" href="#under-slutten" aria-label="Permalink to &quot;Under slutten&quot;">​</a></h3><ul><li>Del observasjoner (&quot;Bakken skråner der igjen&quot;)</li><li>Koordinasjonsstrategi («Bør jeg prøve å blokkere eller gå for poenget?»)</li><li>Tilby støtte («Ta deg god tid, du klarer dette»)</li><li>Juster planene etter hvert som situasjonen endrer seg</li></ul><h3 id="mellom-endene" tabindex="-1">Mellom endene <a class="header-anchor" href="#mellom-endene" aria-label="Permalink to &quot;Mellom endene&quot;">​</a></h3><ul><li>Rask oppsummering (hva fungerte, hva fungerte ikke)</li><li>Tilbakestill mentalt</li><li>Gjør deg klar til neste slutt</li><li>Hold kontakten som et team</li></ul><h3 id="etter-kampen" tabindex="-1">Etter kampen <a class="header-anchor" href="#etter-kampen" aria-label="Permalink to &quot;Etter kampen&quot;">​</a></h3><ul><li>Fullstendig debriefing (når det er aktuelt)</li><li>Anerkjenn bidrag</li><li>Identifiser lærdommer</li><li>Oppretthold forholdet</li></ul><h2 id="hvordan-kommunisere" tabindex="-1">Hvordan kommunisere <a class="header-anchor" href="#hvordan-kommunisere" aria-label="Permalink to &quot;Hvordan kommunisere&quot;">​</a></h2><h3 id="vær-tydelig-og-spesifikk" tabindex="-1">Vær tydelig og spesifikk <a class="header-anchor" href="#vær-tydelig-og-spesifikk" aria-label="Permalink to &quot;Vær tydelig og spesifikk&quot;">​</a></h3><p><strong>Vag:</strong> «Prøv å komme nær» <strong>Fjern:</strong> «Sikt mot venstre side av jekken, ca. 20 cm ut»</p><p><strong>Vag:</strong> «Godt forsøk» <strong>Klar:</strong> «God vekt, bare litt til venstre for linjen»</p><h3 id="vær-konstruktiv" tabindex="-1">Vær konstruktiv <a class="header-anchor" href="#vær-konstruktiv" aria-label="Permalink to &quot;Vær konstruktiv&quot;">​</a></h3><p>Fokuser på løsninger, ikke problemer:</p><p><strong>Problemfokusert:</strong> «Du bommer stadig til høyre» <strong>Løsningsfokusert:</strong> «Kanskje prøve å sikte litt mer til venstre for å kompensere?»</p><h3 id="vær-støttende" tabindex="-1">Vær støttende <a class="header-anchor" href="#vær-støttende" aria-label="Permalink to &quot;Vær støttende&quot;">​</a></h3><p>Tonen din er like viktig som ordene dine:</p><ul><li>Hold deg rolig, selv når du er frustrert</li><li>Bruk oppmuntrende kroppsspråk</li><li>Anerkjenn innsatsen, ikke bare resultatene</li><li>Bygg opp, ikke riv ned</li></ul><h3 id="lytt-aktivt" tabindex="-1">Lytt aktivt <a class="header-anchor" href="#lytt-aktivt" aria-label="Permalink to &quot;Lytt aktivt&quot;">​</a></h3><p>Kommunikasjon er toveis:</p><ul><li>Gi full oppmerksomhet når lagkamerater snakker</li><li>Still oppklarende spørsmål</li><li>Anerkjenn det du har hørt</li><li>Ikke avbryt eller avvis</li></ul><h2 id="kommunikasjonsutfordringer" tabindex="-1">Kommunikasjonsutfordringer <a class="header-anchor" href="#kommunikasjonsutfordringer" aria-label="Permalink to &quot;Kommunikasjonsutfordringer&quot;">​</a></h2><h3 id="uenighet-om-strategi" tabindex="-1">Uenighet om strategi <a class="header-anchor" href="#uenighet-om-strategi" aria-label="Permalink to &quot;Uenighet om strategi&quot;">​</a></h3><p><strong>Dårlig tilnærming:</strong></p><ul><li>Insister på din vei</li><li>Bli defensiv</li><li>Gi etter bittert</li><li>Krangle underveis i spillet</li></ul><p><strong>Bedre tilnærming:</strong></p><ol><li>Del ditt perspektiv tydelig</li><li>Lytt fullt ut til dem</li><li>Diskuter kort fordeler og ulemper</li><li>Bestem sammen (eller overlat til utpekt leder)</li><li>Forplikt deg fullt ut til avgjørelsen</li><li>Gjennomgang etter kampen</li></ol><h3 id="etter-en-lagkamerats-feil" tabindex="-1">Etter en lagkamerats feil <a class="header-anchor" href="#etter-en-lagkamerats-feil" aria-label="Permalink to &quot;Etter en lagkamerats feil&quot;">​</a></h3><p><strong>Hva de trenger:</strong></p><ul><li>Rask bekreftelse</li><li>Tillatelse til å gå videre</li><li>Tillit til at du fortsatt stoler på dem</li><li>Fokuser på neste kast</li></ul><p><strong>Hva skal man si:</strong></p><ul><li>&quot;Ingen problem, neste&quot;</li><li>&quot;Tøff pause, du har den neste&quot;</li><li>&quot;Vi er fortsatt inne i dette&quot;</li><li><em>Noen ganger er bare et nikk eller et klapp nok</em></li></ul><p><strong>Hva du IKKE skal si:</strong></p><ul><li>Ingenting (stillhet føles som dom)</li><li>«Det er greit» (kan høres avvisende ut)</li><li>Alt om hva som gikk galt (ikke nå)</li><li>Synlig frustrasjon (kroppsspråk teller)</li></ul><h3 id="nar-du-gjør-en-feil" tabindex="-1">Når du gjør en feil <a class="header-anchor" href="#nar-du-gjør-en-feil" aria-label="Permalink to &quot;Når du gjør en feil&quot;">​</a></h3><p><strong>Hva du skal gjøre:</strong></p><ul><li>Kort takknemlighet (&quot;Min feil&quot;)</li><li>Ikke unnskyld for mye</li><li>Ikke kom med unnskyldninger</li><li>Tilbakestill og fokuser på neste kast</li><li>Stol på at lagkameratene dine støtter deg</li></ul><h3 id="spenning-i-laget" tabindex="-1">Spenning i laget <a class="header-anchor" href="#spenning-i-laget" aria-label="Permalink to &quot;Spenning i laget&quot;">​</a></h3><p>Hvis spenningen bygger seg opp under en kamp:</p><ol><li>Innse at det skjer</li><li>Ta pusten før du svarer</li><li>Fokuser på spillet, ikke konflikten</li><li>Ta det opp ordentlig etter kampen</li><li>Ikke la det påvirke spillet ditt</li></ol><h2 id="ikke-verbal-kommunikasjon" tabindex="-1">Ikke-verbal kommunikasjon <a class="header-anchor" href="#ikke-verbal-kommunikasjon" aria-label="Permalink to &quot;Ikke-verbal kommunikasjon&quot;">​</a></h2><p>Mye av teamkommunikasjonen er ikke-verbal:</p><h3 id="positive-signaler" tabindex="-1">Positive signaler <a class="header-anchor" href="#positive-signaler" aria-label="Permalink to &quot;Positive signaler&quot;">​</a></h3><ul><li>Øyekontakt</li><li>Nikker</li><li>Tommel opp</li><li>Avslappet holdning</li><li>Beveger seg mot lagkamerater</li><li>Smilende (når det passer)</li></ul><h3 id="negative-signaler-unnga-disse" tabindex="-1">Negative signaler (unngå disse) <a class="header-anchor" href="#negative-signaler-unnga-disse" aria-label="Permalink to &quot;Negative signaler (unngå disse)&quot;">​</a></h3><ul><li>Øynerulling</li><li>Vender seg bort</li><li>Kryssede armer</li><li>Sukking</li><li>Rister på hodet</li><li>Anspent kroppsspråk</li></ul><p><strong>Husk:</strong> Lagkameratene dine ser alt. Kroppsspråket ditt påvirker selvtilliten og prestasjonene deres.</p><h2 id="a-bygge-kommunikasjonsvaner" tabindex="-1">Å bygge kommunikasjonsvaner <a class="header-anchor" href="#a-bygge-kommunikasjonsvaner" aria-label="Permalink to &quot;Å bygge kommunikasjonsvaner&quot;">​</a></h2><h3 id="praksiskommunikasjon" tabindex="-1">Praksiskommunikasjon <a class="header-anchor" href="#praksiskommunikasjon" aria-label="Permalink to &quot;Praksiskommunikasjon&quot;">​</a></h3><p>Ikke vent på at konkurrentene skal kommunisere:</p><ul><li>Øv på strategiske diskusjoner i opplæringen</li><li>Gi hverandre tilbakemeldinger regelmessig</li><li>Utvikle lagspråket ditt</li><li>Bygg komfort med ærlige samtaler</li></ul><h3 id="utvikle-teamsignaler" tabindex="-1">Utvikle teamsignaler <a class="header-anchor" href="#utvikle-teamsignaler" aria-label="Permalink to &quot;Utvikle teamsignaler&quot;">​</a></h3><p>Noen lag utvikler stenografi:</p><ul><li>Håndsignaler for strategi</li><li>Kodeord for situasjoner</li><li>Raske fraser med felles betydning</li></ul><h3 id="regelmessige-innsjekkinger" tabindex="-1">Regelmessige innsjekkinger <a class="header-anchor" href="#regelmessige-innsjekkinger" aria-label="Permalink to &quot;Regelmessige innsjekkinger&quot;">​</a></h3><p>Utenom spill:</p><ul><li>Hvordan jobber vi sammen?</li><li>Hva går bra?</li><li>Hva kunne vært bedre?</li><li>Noen problemer som må tas opp?</li></ul><h2 id="kapteinens-rolle" tabindex="-1">Kapteinens rolle <a class="header-anchor" href="#kapteinens-rolle" aria-label="Permalink to &quot;Kapteinens rolle&quot;">​</a></h2><p>Hvis teamet ditt har en utpekt leder:</p><p><strong>Kapteinens ansvar:</strong></p><ul><li>Endelig avgjørelse når teamet er uenig</li><li>Setter tonen og energien</li><li>Håndtering av teamdynamikk</li><li>Å holde fokus under press</li></ul><p><strong>Alle andre:</strong></p><ul><li>Del ditt perspektiv</li><li>Støtt avgjørelsen når den er tatt</li><li>Bidra til å opprettholde teamenergien</li><li>Ta ansvar for din rolle</li></ul><h2 id="viktig-konklusjon" tabindex="-1">Viktig konklusjon <a class="header-anchor" href="#viktig-konklusjon" aria-label="Permalink to &quot;Viktig konklusjon&quot;">​</a></h2><blockquote><p>Gode team snakker med hverandre, ikke om hverandre. De kommuniserer med ærlighet, respekt og en felles forpliktelse til suksess.</p></blockquote><p>Øv på kommunikasjon slik du øver på å kaste. Det er en ferdighet som forbedres med oppmerksomhet.</p>',68))])}]]);export{d as __pageData,m as default};
